pm.test('Status code is 201', function() {
  pm.response.to.have.status(201);
});

const res = pm.response.json();

pm.test('Response contains short URL data', function() {
  pm.expect(res.data).to.have.property('short_code');
  pm.expect(res.data).to.have.property('short_url');
  pm.expect(res.data).to.have.property('original_url');
  pm.expect(res.data).to.have.property('created_at');
});

pm.test('short_code is Base62 encoded', function() {
  const code = res.data.short_code;
  // Base62 contains alphanumeric: 0-9, a-z, A-Z
  pm.expect(code).to.match(/^[0-9a-zA-Z]+$/);
  pm.expect(code.length).to.be.above(0);
});

pm.test('short_url is valid', function() {
  pm.expect(res.data.short_url).to.include(res.data.short_code);
  pm.expect(res.data.short_url).to.be.a('string');
});

// Save for analytics queries
if (res.data) {
  pm.collectionVariables.set('short_code', res.data.short_code);
  console.log('✓ Short code saved:', res.data.short_code);
}

